CREATE TABLE space_message_receipts (id VARCHAR(64) PRIMARY KEY, space_id VARCHAR(191) NOT NULL, message_id VARCHAR(191) NOT NULL, user_id VARCHAR(191) NOT NULL, status VARCHAR(16) NOT NULL, acknowledged_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_space_message_receipts_member (space_id, message_id, user_id), CONSTRAINT fk_space_message_receipts_space FOREIGN KEY (space_id) REFERENCES collaboration_spaces(id) ON DELETE CASCADE, CONSTRAINT fk_space_message_receipts_message FOREIGN KEY (message_id) REFERENCES space_messages(id) ON DELETE CASCADE, CONSTRAINT fk_space_message_receipts_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT chk_space_message_receipts_status CHECK (status IN ('delivered', 'acknowledged')));
-- statement-break
CREATE INDEX idx_space_message_receipts_message ON space_message_receipts(space_id, message_id);
